// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::coplanar::coplanar_triangle_interiors_overlap;
use super::misc::rc3;
use super::misc::sorted2;
use super::point::point_in_triangle_3d;
use super::types::RecoveredFacet;
use crate::mesh::types::Point;
use std::collections::{HashMap, HashSet, VecDeque};

pub(super) fn facet_shells(facets: &[RecoveredFacet]) -> Vec<Vec<usize>> {
    let mut edge_to_facets: HashMap<[usize; 2], Vec<usize>> = HashMap::new();
    for (idx, facet) in facets.iter().enumerate() {
        let [a, b, c] = facet.nodes;
        for edge in [sorted2([a, b]), sorted2([b, c]), sorted2([c, a])] {
            edge_to_facets.entry(edge).or_default().push(idx);
        }
    }

    let mut visited = vec![false; facets.len()];
    let mut shells = Vec::new();
    for seed in 0..facets.len() {
        if visited[seed] {
            continue;
        }
        visited[seed] = true;
        let mut shell = Vec::new();
        let mut queue = VecDeque::from([seed]);
        while let Some(idx) = queue.pop_front() {
            shell.push(idx);
            let [a, b, c] = facets[idx].nodes;
            for edge in [sorted2([a, b]), sorted2([b, c]), sorted2([c, a])] {
                let Some(neighbors) = edge_to_facets.get(&edge) else {
                    continue;
                };
                for &neighbor in neighbors {
                    if !visited[neighbor] {
                        visited[neighbor] = true;
                        queue.push_back(neighbor);
                    }
                }
            }
        }
        shells.push(shell);
    }
    shells
}

pub(super) fn facet_side(points: &[Point], facet: [usize; 3], vertex: usize) -> i8 {
    let sign = robust::orient3d(
        rc3(points[facet[0]]),
        rc3(points[facet[1]]),
        rc3(points[facet[2]]),
        rc3(points[vertex]),
    );
    if sign > 0.0 {
        1
    } else if sign < 0.0 {
        -1
    } else {
        0
    }
}

/// A sum of contained triangle areas is an exact coverage proof only when no
/// two candidate interiors overlap. Without this check, overlapping triangles
/// can have the target's total area while leaving a compensating hole.
pub(super) fn facet_tiling_has_disjoint_interiors(
    points: &[Point],
    facets: &[RecoveredFacet],
) -> bool {
    for (index, left) in facets.iter().enumerate() {
        for right in &facets[index + 1..] {
            if coplanar_triangle_interiors_overlap(points, left.nodes, right.nodes) {
                return false;
            }
        }
    }
    true
}

/// Transversal pierce point: a Delaunay edge passing through the interior of
/// `facet` (endpoints strictly on opposite sides). Coplanar blockers are
/// handled at the constraint-edge level instead.
pub(super) fn facet_pierce_point(
    points: &[Point],
    tet_edges: &HashSet<[usize; 2]>,
    facet: [usize; 3],
) -> Option<Point> {
    let a = points[facet[0]];
    let b = points[facet[1]];
    let c = points[facet[2]];
    for &edge in tet_edges {
        if facet.contains(&edge[0]) || facet.contains(&edge[1]) {
            continue;
        }
        let p = points[edge[0]];
        let q = points[edge[1]];
        let sp = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(p));
        let sq = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(q));
        if sp == 0.0 || sq == 0.0 || sp.signum() == sq.signum() {
            continue;
        }
        let t = sp / (sp - sq);
        if !(0.0..=1.0).contains(&t) {
            continue;
        }
        let hit = Point::new_3d(
            p.x + (q.x - p.x) * t,
            p.y + (q.y - p.y) * t,
            p.z + (q.z - p.z) * t,
        );
        if point_in_triangle_3d(hit, a, b, c) {
            return Some(hit);
        }
    }
    None
}
